import type { AssetIconProps } from "./asset-icon.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import {
  Agent,
  AgentRemix,
  Apps,
  AppsRemix,
  ConnectionRemix,
  Data,
  DataRemix,
  Documents,
  DocumentsRemix,
  File,
  FileRemix,
  FormRemix,
  Forms,
  Orchestration,
  OrchestrationRemix,
  Page,
  PageRemix,
  Persona,
  PersonaRemix,
  Process,
  ProcessRemix,
  Theme,
  ThemeRemix,
  UserStory,
  UserStoryRemix,
  Workflow,
  WorkflowRemix,
} from "@exp-textura/icons";

import { AssetIconClasses, StyledAssetIcon } from "./asset-icon.styles";

const ICON_MAP = {
  default: { solid: AppsRemix, line: Apps },
  app: { solid: AppsRemix, line: Apps },
  page: { solid: PageRemix, line: Page },
  form: { solid: FormRemix, line: Forms },
  theme: { solid: ThemeRemix, line: Theme },
  workflow: { solid: WorkflowRemix, line: Workflow },
  orchestration: { solid: OrchestrationRemix, line: Orchestration },
  agent: { solid: AgentRemix, line: Agent },
  document: { solid: DocumentsRemix, line: Documents },
  file: { solid: FileRemix, line: File },
  connection: { solid: ConnectionRemix, line: ConnectionRemix },
  table: { solid: DataRemix, line: Data },
  persona: { solid: PersonaRemix, line: Persona },
  "user-story": { solid: UserStoryRemix, line: UserStory },
  process: { solid: ProcessRemix, line: Process },
};

const AssetIcon = forwardRef(
  (
    {
      className,
      variant = "app",
      size = "lg",
      utility = "default",
      children,
      ...props
    }: AssetIconProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();

    const isOutline = utility === "outline";
    const useLineIcon = !isOutline && (size === "sm" || size === "md");

    const Icon = useLineIcon
      ? ICON_MAP[variant as keyof typeof ICON_MAP].line
      : ICON_MAP[variant as keyof typeof ICON_MAP].solid;

    const rootClasses = clsx(AssetIconClasses.root, className, {
      [AssetIconClasses[size]]: size,
      [AssetIconClasses.outline]: isOutline,
    });

    return (
      <StyledAssetIcon
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {children ? (
          React.cloneElement(children as React.ReactElement, {
            className: AssetIconClasses.icon,
          })
        ) : (
          <Icon className={AssetIconClasses.icon} />
        )}
      </StyledAssetIcon>
    );
  },
);

AssetIcon.displayName = "AssetIcon";

export default AssetIcon;
